import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.BGlkWkwp.js";const u=JSON.parse('{"title":"Slider","description":"","frontmatter":{},"headers":[],"relativePath":"components/slider.md","filePath":"components/slider.md"}'),r={name:"components/slider.md"};function i(s,e,n,l,h,c){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="slider" tabindex="-1">Slider <a class="header-anchor" href="#slider" aria-label="Permalink to &quot;Slider&quot;">​</a></h1><p>Slider is the input of a value on a range.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for a value where the position matters more than the exact number, such as an opacity. <code>display</code> shows the value with its unit; <code>oninput</code> follows the drag and <code>onchange</code> gives the value when it is let go. For an exact number use a <a href="./number-input">NumberInput</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>value</code></td><td>required</td><td>The value</td></tr><tr><td><code>min</code></td><td><code>0</code></td><td>The least value</td></tr><tr><td><code>max</code></td><td><code>100</code></td><td>The greatest value</td></tr><tr><td><code>step</code></td><td><code>1</code></td><td>The step</td></tr><tr><td><code>display</code></td><td></td><td>The value as shown on the right, with its unit</td></tr><tr><td><code>ariaLabel</code></td><td></td><td>The accessible name</td></tr><tr><td><code>disabled</code></td><td><code>false</code></td><td>Cannot be changed</td></tr><tr><td><code>id</code></td><td></td><td>The id of the input</td></tr><tr><td><code>oninput</code></td><td></td><td>Called with each value while dragging</td></tr><tr><td><code>onchange</code></td><td></td><td>Called with the value when it is let go</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The control is as high as a small button, and the whole of it can be dragged. It is a native range input, so the keys and screen readers work as the browser does. The track is two lines thick, solid on the side that has been passed; the thumb is the square of an icon. The value sits gap-sm to the right in a slot of fixed width, aligned to its end and trimmed to its ink. Disabled is dimmed.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/slider/" title="Slider" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/slider/" target="_blank" rel="noopener">Slider</a></figcaption></figure>',10)])])}const m=t(r,[["render",i]]);export{u as __pageData,m as default};
